include  <p>XboxController controller; Servo brazoServo;</p> <p>// Pines TB6612FNG const int pinPWMA = 14; const int pinAIN1 = 27; const int pinAIN2 = 26; const int pinBIN1 = 25; const int pinBIN2 = 33; const int pinPWMB = 32; const int pinSTBY = 4;</p> <p>// Servo SG90 (mecanismo de tiro) const int pinSERVO = 13; const int POS_REPOSO = 0; const int POS_GOLPE  = 90;</p> <p>// LED integrado: parpadea buscando control, fijo si esta conectado const int pinLED = 2;</p> <p>// ================== AJUSTES ================== const bool INVERTIR_Y = false;       // si empujas arriba y va hacia atras, pon true const bool INVERTIR_X = false;       // si gira al lado contrario, pon true const bool INVERTIR_MOTOR_A = true; // motor izquierdo (si gira al reves, pon true) const bool INVERTIR_MOTOR_B = false; // motor derecho</p> <p>const float ZONA_MUERTA = 0.12; const int   PWM_MINIMO  = 60; const int   NIVELES[3]  = {150, 210, 255};  // R2: 3 niveles (baja, media, alta) int nivel = 1;                              // arranca en media</p> <p>const int PASO_ACEL = 25;                   // aceleracion limitada por tick const unsigned long PERIODO_CONTROL = 10;</p> <p>// Tiro const unsigned long TIEMPO_GOLPE   = 120; const unsigned long TIEMPO_RECARGA = 300;</p> <p>// R4: se detiene siempre que el control se desconecta. // Opcional: detener si la palanca no cambia en este tiempo const bool USAR_WATCHDOG = false; const unsigned long TIEMPO_FAILSAFE = 1000;</p> <p>const bool DEBUG = true; // =============================================</p> <p>const int PWM_FREQ = 20000; const int PWM_RES  = 8;</p> <p>// Estado de motores (con signo: positivo adelante, negativo atras) int actualA = 0; int actualB = 0;</p> <p>// Estado del tiro enum EstadoTiro { TIRO_LIBRE, TIRO_EXTENDIDO, TIRO_RECARGA }; EstadoTiro estadoTiro = TIRO_LIBRE; unsigned long inicioTiro = 0;</p> <p>// Estado de botones y reportes bool prevLB = false, prevRB = false, prevTiro = false; float ultX = 0, ultY = 0; unsigned long ultimoCambio = 0; unsigned long ultimoControl = 0; unsigned long ultimoDebug = 0; unsigned long reportes = 0;</p> <p>// ---------- Motores ---------- void direccionMotor(int in1, int in2, int valor) {   if (valor &gt; 0) {     digitalWrite(in1, HIGH); digitalWrite(in2, LOW);   } else if (valor &lt; 0) {     digitalWrite(in1, LOW);  digitalWrite(in2, HIGH);   } else {     digitalWrite(in1, HIGH); digitalWrite(in2, HIGH);  // freno corto   } }</p> <p>void escribirMotores(int a, int b) {   if (INVERTIR_MOTOR_A) a = -a;   if (INVERTIR_MOTOR_B) b = -b;   direccionMotor(pinAIN1, pinAIN2, a);   direccionMotor(pinBIN1, pinBIN2, b);   ledcWrite(pinPWMA, abs(a));   ledcWrite(pinPWMB, abs(b)); }</p> <p>void detenerTodo() {   actualA = 0;   actualB = 0;   escribirMotores(0, 0); }</p> <p>// Aceleracion limitada; frenar o bajar velocidad es inmediato int rampa(int actual, int objetivo) {   if ((actual &gt; 0 &amp;&amp; objetivo &lt; 0) || (actual &lt; 0 &amp;&amp; objetivo &gt; 0)) actual = 0;   if (abs(objetivo) &lt;= abs(actual)) return objetivo;   if (objetivo &gt; 0) return min(actual + PASO_ACEL, objetivo);   return max(actual - PASO_ACEL, objetivo); }</p> <p>int valorPWM(float v) {   float a = fabsf(v);   if (a &lt; 0.03) return 0;   int pwm = PWM_MINIMO + (int)(a * (NIVELES[nivel] - PWM_MINIMO));   return v &gt; 0 ? pwm : -pwm; }</p> <p>// Mezcla tipo "arcade": Y = avance, X = giro void calcularObjetivo(float x, float y, int &amp;objA, int &amp;objB) {   float mag = sqrtf(x * x + y * y);   if (mag &lt; ZONA_MUERTA) { objA = 0; objB = 0; return; }   if (mag &gt; 1.0f) { x /= mag; y /= mag; mag = 1.0f; }   float escala = (mag - ZONA_MUERTA) / (1.0f - ZONA_MUERTA);   x = x / mag * escala;   y = y / mag * escala;</p> <p>float izq = y + x;  // motor A = izquierdo   float der = y - x;  // motor B = derecho   float mx = fmaxf(fabsf(izq), fabsf(der));   if (mx &gt; 1.0f) { izq /= mx; der /= mx; }</p> <p>objA = valorPWM(izq);   objB = valorPWM(der); }</p> <p>// ---------- Tiro (servo) ---------- void iniciarTiro() {   if (estadoTiro != TIRO_LIBRE) return;   if (!brazoServo.attached()) brazoServo.attach(pinSERVO, 500, 2400);   brazoServo.write(POS_GOLPE);   inicioTiro = millis();   estadoTiro = TIRO_EXTENDIDO; }</p> <p>void actualizarTiro(unsigned long ahora) {   switch (estadoTiro) {     case TIRO_EXTENDIDO:       if (ahora - inicioTiro &gt;= TIEMPO_GOLPE) {         brazoServo.write(POS_REPOSO);         estadoTiro = TIRO_RECARGA;       }       break;     case TIRO_RECARGA:       if (ahora - inicioTiro &gt;= TIEMPO_GOLPE + TIEMPO_RECARGA) {         brazoServo.detach();         estadoTiro = TIRO_LIBRE;       }       break;     default:       break;   } }</p> <p>void setup() {   Serial.begin(115200);   delay(500);</p> <p>Serial.println();   Serial.println("========================================");   Serial.println("   CARRITO FUTBOL - CONTROL XBOX");   Serial.println("========================================");</p> <p>ESP32PWM::allocateTimer(0);   brazoServo.setPeriodHertz(50);   brazoServo.attach(pinSERVO, 500, 2400);   brazoServo.write(POS_REPOSO);   delay(400);   brazoServo.detach();</p> <p>pinMode(pinAIN1, OUTPUT);   pinMode(pinAIN2, OUTPUT);   pinMode(pinBIN1, OUTPUT);   pinMode(pinBIN2, OUTPUT);   pinMode(pinSTBY, OUTPUT);   digitalWrite(pinSTBY, HIGH);   pinMode(pinLED, OUTPUT);</p> <p>ledcAttachChannel(pinPWMA, PWM_FREQ, PWM_RES, 4);   ledcAttachChannel(pinPWMB, PWM_FREQ, PWM_RES, 5);</p> <p>detenerTodo();</p> <p>controller.begin();   Serial.println("Esperando control Xbox...");   ultimoCambio = millis(); }</p> <p>void loop() {   unsigned long ahora = millis();   actualizarTiro(ahora);</p> <p>if (!controller.isConnected()) {     detenerTodo();     prevLB = prevRB = prevTiro = false;     ultimoCambio = ahora;     digitalWrite(pinLED, (ahora / 250) % 2);</p> <pre><code>static unsigned long ultimoMensaje = 0;
if (ahora - ultimoMensaje &gt; 1000) {
  Serial.println("Control no conectado...");
  ultimoMensaje = ahora;
}
delay(10);
return;
</code></pre> <p>}</p> <p>digitalWrite(pinLED, HIGH);</p> <p>XboxControlsState s;   controller.read(&amp;s);</p> <p>bool lb = s.leftBumper, rb = s.rightBumper;   if (rb &amp;&amp; !prevRB &amp;&amp; nivel &lt; 2) { nivel++; Serial.printf("Nivel %d\n", nivel + 1); }   if (lb &amp;&amp; !prevLB &amp;&amp; nivel &gt; 0) { nivel--; Serial.printf("Nivel %d\n", nivel + 1); }   prevLB = lb;   prevRB = rb;</p> <p>bool pedirTiro = s.buttonA || (s.rightTrigger &gt; 0.5);   if (pedirTiro &amp;&amp; !prevTiro) iniciarTiro();   prevTiro = pedirTiro;</p> <p>if (s.leftStickX != ultX || s.leftStickY != ultY) {     ultX = s.leftStickX;     ultY = s.leftStickY;     ultimoCambio = ahora;     reportes++;   }</p> <p>if (ahora - ultimoControl &gt;= PERIODO_CONTROL) {     ultimoControl = ahora;</p> <pre><code>float x = s.leftStickX;
float y = s.leftStickY;
if (INVERTIR_Y) y = -y;
if (INVERTIR_X) x = -x;

int objA, objB;
calcularObjetivo(x, y, objA, objB);

if (s.buttonB) { objA = 0; objB = 0; }

if (USAR_WATCHDOG &amp;&amp; (objA != 0 || objB != 0) &amp;&amp; (ahora - ultimoCambio &gt;= TIEMPO_FAILSAFE)) {
  objA = 0;
  objB = 0;
}

actualA = rampa(actualA, objA);
actualB = rampa(actualB, objB);
escribirMotores(actualA, actualB);

if (DEBUG &amp;&amp; ahora - ultimoDebug &gt;= 250) {
  Serial.printf("X:%6.2f Y:%6.2f | A:%4d B:%4d | nivel:%d | rep/s:%lu\n",
                x, y, actualA, actualB, nivel + 1, reportes * 4);
  reportes = 0;
  ultimoDebug = ahora;
}
</code></pre> <p>} }</p>
